def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    # Create a graph adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Get unique weights and sort them for binary search
    weights = sorted(set(w for u, v, w in edges))

    def can_form_graph(max_weight: int) -> bool:
        # Create a new graph with edges <= max_weight
        filtered_graph = [[] for _ in range(n)]
        for u in range(n):
            for v, w in graph[u]:
                if w <= max_weight:
                    filtered_graph[u].append(v)

        # Check reachability from all other nodes to node 0
        for start in range(1, n):
            stack = [start]
            visited = [False] * n
            while stack:
                node = stack.pop()
                for neighbor in filtered_graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            if not visited[0]:
                return False

        # Check outgoing edges constraint
        out_degree = [0] * n
        for u in range(n):
            for v in filtered_graph[u]:
                out_degree[u] += 1
                if out_degree[u] > threshold:
                    return False
        return True

    answer = -1
    left, right = 0, len(weights) - 1
    while left <= right:
        mid = (left + right) // 2
        if can_form_graph(weights[mid]):
            answer = weights[mid]
            right = mid - 1
        else:
            left = mid + 1

    return answer

