def minCost(n: int, cost: List[List[int]]) -> int:
    # Initialize dp array to store minimum costs
    dp = [[0] * 3 for _ in range(n)]

    # Base case for the first house
    for j in range(3):
        dp[0][j] = cost[0][j]

    # Fill dp array while considering adjacency constraints
    for i in range(1, n):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(dp[i-1][(j+1) % 3], dp[i-1][(j+2) % 3])

    # Handle equidistant constraints separately by checking pairs
    min_cost = float('inf')
    for j in range(3):
        for k in range(3):
            if j != k:
                # Calculate cost for first half and second half with colors j and k
                cost_pair = dp[n//2 - 1][j] + dp[n - 1][k]
                min_cost = min(min_cost, cost_pair)

    return min_cost

